      const ba = ZOO[birthAnimalName];
      const currentYearAnimal = Object.keys(ZOO).find(k => ZOO[k] === getAnimalFromYear(ry)) || '';
      const cat = birthAnimalName && currentYearAnimal ? getCategory(birthAnimalName, currentYearAnimal) : 'neutral';
